class Solution {
    public int trap(int[] height) {
        int n = height.length;
        int total = 0;

        for (int i = 0; i < n; i++) {
            int leftMax = 0;
            for (int j = i - 1; j >= 0; j--) {
                leftMax = Math.max(leftMax, height[j]);
            }
            int rightMax = 0;
            for (int j = i + 1; j < n; j++) {
                rightMax = Math.max(rightMax, height[j]);
            }
            // 水面高度由左右最高中较矮的那个决定，柱子本身要减掉
            int water = Math.min(leftMax, rightMax) - height[i];
            if (water > 0) total += water;
        }
        return total;
    }
}

class Solution {
    public int trap(int[] height) {
        int n = height.length;
        if (n < 3) return 0;

        int[] leftMax = new int[n];
        int[] rightMax = new int[n];

        // leftMax[i] = i 左边（不含 i）的最高柱子
        leftMax[0] = 0;
        for (int i = 1; i < n; i++) {
            leftMax[i] = Math.max(leftMax[i - 1], height[i - 1]);
        }

        // rightMax[i] = i 右边（不含 i）的最高柱子
        rightMax[n - 1] = 0;
        for (int i = n - 2; i >= 0; i--) {
            rightMax[i] = Math.max(rightMax[i + 1], height[i + 1]);
        }

        int total = 0;
        for (int i = 0; i < n; i++) {
            int water = Math.min(leftMax[i], rightMax[i]) - height[i];
            if (water > 0) total += water;
        }
        return total;
    }
}

class Solution {
    public int trap(int[] height) {
        int left = 0, right = height.length - 1;
        int leftMax = 0, rightMax = 0;
        int total = 0;

        while (left <= right) {
            if (leftMax < rightMax) {
                // 左侧瓶颈确定，可以结算 left 这一格
                if (height[left] > leftMax) {
                    leftMax = height[left];   // 自己成了新的左边最高，此处积水为 0
                } else {
                    total += leftMax - height[left];
                }
                left++;
            } else {
                // 右侧瓶颈确定，可以结算 right 这一格
                if (height[right] > rightMax) {
                    rightMax = height[right];
                } else {
                    total += rightMax - height[right];
                }
                right--;
            }
        }
        return total;
    }
}
